import pickle
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/load_config')
def load_config():
    '''
    Tải cấu hình từ yêu cầu bằng cách sử dụng 'config'.
    Sử dụng pickle để giải mã cấu hình sau khi chuyển đổi nó từ hex sang bytes.
    '''
    config_hex = request.args.get('config')

    if not config_hex:
        return jsonify({"error": "Missing 'config' parameter."}), 400

    try:
        # Convert hex string to bytes
        config_bytes = bytes.fromhex(config_hex)

        # Unpickle the bytes to get the configuration
        config = pickle.loads(config_bytes)

        return jsonify({"config": config})
    except ValueError:
        return jsonify({"error": "Invalid hex string provided for 'config'."}), 400
    except pickle.UnpicklingError:
        return jsonify({"error": "Invalid or corrupted pickle data provided."}), 400
    except Exception as e:
        return jsonify({"error": f"An unexpected error occurred: {str(e)}"}), 500

