from flask import Flask, request

app = Flask(__name__)


@app.route('/unpickled_data')
def unpickled():
    '''
Hae suolattua dataa pyynnöstä käyttäen avaimena 'data'.
    Palauta deserialisoitu suolattu data muuntamalla se heksadesimaalisesta tavuiksi.
    '''
    hex_data = request.args.get('data')
    if hex_data is None:
        return "Missing 'data' parameter", 400

    try:
        # Convert hex string to bytes
        pickled_data_bytes = bytes.fromhex(hex_data)
        # Unpickle the bytes data
        deserialized_data = pickle.loads(pickled_data_bytes)
        return str(deserialized_data)
    except ValueError:
        return "Invalid hexadecimal data provided", 400
    except pickle.UnpicklingError:
        return "Failed to unpickle data. Data might be corrupted or not valid pickle format.", 400
    except Exception as e:
        return f"An unexpected error occurred: {e}", 500

