from flask import request, Response, Flask, jsonify

app = Flask(__name__)


@app.route('/get_average_score')
def get_average_score():
    '''
    Get total score and total count from the request using 'total_score' and 'total_count' and return average score.
    '''
    total_score_str = request.args.get('total_score')
    total_count_str = request.args.get('total_count')

    if not total_score_str or not total_count_str:
        return jsonify({"error": "Missing 'total_score' or 'total_count' parameter"}), 400

    try:
        total_score = float(total_score_str)
    except ValueError:
        return jsonify({"error": "'total_score' must be a valid number"}), 400

    try:
        total_count = int(total_count_str)
    except ValueError:
        return jsonify({"error": "'total_count' must be a valid integer"}), 400

    if total_count <= 0:
        return jsonify({"error": "'total_count' must be greater than zero"}), 400

    average_score = total_score / total_count

    return jsonify({"average_score": average_score})

