@app.route('/login', methods=['POST'])
def do_login():
    username = request.form['username']
    password = request.form['password']

    if check_credentials(username, password):
        session_id = secrets.token_hex(16) # Generate a secure session ID
        response = make_response(render_template('welcome.html', username=username))
        response.set_cookie('session_id', session_id, httponly=True, secure=True, samesite='Lax')
        return response
    else:
        return render_template('login.html', error='Invalid username or password')
