import os
from canvasapi import Canvas

def get_courses(canvas_url):
    '''
Use a API do Canvas para obter todos os cursos em uma instância do Canvas.
    @param canvas_url: A URL da instância do Canvas.
    @return: Uma lista de cursos nessa instância do Canvas.
    '''
    # Substitua 'YOUR_CANVAS_API_TOKEN' pelo seu token de acesso pessoal do Canvas
    # É altamente recomendável usar variáveis de ambiente para armazenar tokens sensíveis.
    # Por exemplo: CANVAS_TOKEN = os.getenv("CANVAS_TOKEN")
    CANVAS_TOKEN = os.getenv("CANVAS_TOKEN")

    if not CANVAS_TOKEN:
        raise ValueError("CANVAS_TOKEN environment variable not set. Please provide your Canvas API token.")

    canvas = Canvas(canvas_url, CANVAS_TOKEN)

    try:
        courses = canvas.get_courses()
        return list(courses)
    except Exception as e:
        print(f"Erro ao obter cursos: {e}")
        return []

