import os
from canvasapi import Canvas

def get_courses(canvas_url):
    '''
    Use a API do Canvas para obter todos os cursos em uma instância do Canvas.
    É necessário que a variável de ambiente 'CANVAS_API_KEY' esteja definida
    com sua chave de API do Canvas para autenticação.

    @param canvas_url: A URL da instância do Canvas.
    @return: Uma lista de cursos nessa instância do Canvas.
    @raises ValueError: Se a variável de ambiente 'CANVAS_API_KEY' não estiver definida.
    @raises Exception: Para outros erros da API do Canvas.
    '''
    try:
        CANVAS_API_KEY = os.environ.get('CANVAS_API_KEY')
        if not CANVAS_API_KEY:
