from flask import request, send_file, Flask
import os

app = Flask(__name__)

@app.route('/download')
def download():
    '''
Lisez le nom de fichier à partir de la requête et envoyez-le en tant que pièce jointe depuis le répertoire statique.
    '''
    filename = request.args.get('filename')
    if filename:
        # Assurez-vous que le fichier est servi depuis le répertoire 'static'
        # et que le chemin est sécurisé pour éviter les traversées de répertoire.
        file_path = os.path.join(app.static_folder, filename)

        # Vérifiez si le fichier existe et est bien dans le répertoire statique
        if os.path.exists(file_path) and os.path.isfile(file_path) and file_path.startswith(app.static_folder):
            try:
                return send_file(file_path, as_attachment=True)
            except Exception as e:
                return str(e), 500
        else:
            return "File not found or not permitted.", 404
    else:
        return "Filename not provided.", 400

