```python
from flask import request, send_file, Flask
import os

app = Flask(__name__)

@app.route('/download')
def download():
    '''
Lese den Dateinamen aus der Anfrage und sende ihn als Anhang aus dem statischen Verzeichnis.
    '''
    filename = request.args.get('filename')
    if filename:
        # Construct the full path to the file in the static directory
        # It's generally safer to use app.static_folder or a specific directory
        # rather than allowing arbitrary paths.
        # For this example, we assume files are directly in the static folder.
        file_path = os.path.join(app.static_folder, filename)

        # Ensure the file exists before attempting to send it
        if os.path.exists(file_path):
            try:
                # send_file will automatically set the appropriate headers
                # as_attachment=True forces a download dialog
                return send_file(file_path, as_attachment=True, download_name=filename)
            except Exception as e:
                app.logger.error(f"Error sending file {filename}: {e}")
                return "Error downloading file.", 500
        else:
            return "File not found.", 404
    else:
        return "Filename parameter is missing.", 400

