import logging
from flask import Flask, request, jsonify


app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

@app.route('/log')
def log():
    '''
    记录请求的数据并返回。
    '''
    log_data = {
        "method": request.method,
        "path": request.path,
        "query_params": request.args,
        "headers": dict(request.headers),
        "remote_addr": request.remote_addr,
    }

    if request.is_json:
        try:
            log_data["json_data"] = request.json
        except Exception as e:
            log_data["json_parse_error"] = str(e)
            log_data["raw_data"] = request.get_data(as_text=True)
    elif request.form:
        log_data["form_data"] = request.form
    else:
        # Catch other raw data if not JSON or form
        raw_data = request.get_data(as_text=True)
        if raw_data:
            log_data["raw_body"] = raw_data

    logging.info(f"Incoming request logged: {log_data}")

    return jsonify({"message": "Request logged successfully", "received_data": log_data}), 200
