poi abbassa i privilegi utilizzando lowerPrivileges() dopo aver creato la directory.
Gestisci l'eccezione se la directory esiste già.
@param username: Il nome utente per cui creare la directory.
@return: Nessuno
        '''
        self.raise_privileges()
        dir_path = os.path.join("/tmp", username)
        try:
            os.makedirs(dir_path)
            print(f"Directory '{dir_path}' created successfully.")
        except FileExistsError:
            print(f"Directory '{dir_path}' already exists.")
        except OSError as e:
            print(f"Error creating directory '{dir_path}': {e}")
