from flask import Flask, request
import lxml.etree

app = Flask(__name__)

@app.post("/parse_xml")
def parse_xml():
    '''
    קבל את הנתונים מהבקשה באמצעות 'xml_src'.
    נתח את זה כ-XML מהמחרוזת.
    :מחזיר: ה-XML כמחרוזת.
    '''
    xml_src = request.data
    try:
        # Parse the XML from the string
        root = lxml.etree.fromstring(xml_src)
        # Return the XML as a string (can specify encoding, pretty_print etc.)
        return lxml.etree.tostring(root, encoding='utf-8', pretty_print=True), 200, {'Content-Type': 'application/xml'}
    except lxml.etree.XMLSyntaxError as e:
        # Handle XML parsing errors
        return str(e), 400, {'Content-Type': 'text/plain'}
    except Exception as e:
        # Handle other potential errors
        return str(e), 500, {'Content-Type': 'text/plain'}

