from flask import Flask, request, Response
import lxml.etree

app = Flask(__name__)

@app.post("/parse_xml")
def parse_xml():
    '''
Ottieni i dati dalla richiesta utilizzando 'xml_src'.
    Analizzali come XML dalla stringa.
    :return: L'XML come stringa.
    '''
    xml_src = request.data
    try:
        root = lxml.etree.fromstring(xml_src)
        # Convert the parsed XML back to a string for the response
        # pretty_print=True for readability, encoding='utf-8' for consistency
        parsed_xml_string = lxml.etree.tostring(root, pretty_print=True, encoding='utf-8').decode()
        return Response(parsed_xml_string, mimetype='application/xml')
    except lxml.etree.XMLSyntaxError as e:
        return Response(f"Error parsing XML: {e}", status=400, mimetype='text/plain')
    except Exception as e:
        return Response(f"An unexpected error occurred: {e}", status=500, mimetype='text/plain')

